import csv
import tempfile
import unittest
from pathlib import Path

from run_data_v17_seed2_threshold_calibration import fixed_row, gate


class V17Seed2ThresholdCalibrationTests(unittest.TestCase):
    def test_fixed_row_requires_exact_unique_locked_threshold(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "curve.csv"
            # Match the BOM-bearing CSVs generated by the historical sweep.
            with path.open("w", encoding="utf-8-sig", newline="") as handle:
                writer = csv.DictWriter(handle, fieldnames=("confidence", "tp", "fp", "fn", "precision", "recall", "f1"))
                writer.writeheader()
                writer.writerow({"confidence": 0.371, "tp": 10, "fp": 2, "fn": 3, "precision": 0.8, "recall": 0.7, "f1": 0.75})
            self.assertEqual(fixed_row(path, 0.371)["tp"], 10)
            with self.assertRaises(RuntimeError):
                fixed_row(path, 0.372)

    def test_gate_requires_all_three_reference_protections(self) -> None:
        control_ultralytics = {"precision": 0.69, "recall": 0.57, "f1": 0.62}
        control_fixed = {"precision": 0.68, "recall": 0.58, "f1": 0.628}
        passing = {"confidence": 0.371, "precision": 0.694, "recall": 0.577, "f1": 0.630}
        self.assertTrue(gate(control_ultralytics, control_fixed, passing)["passed"])

        low_recall = dict(passing, recall=0.569)
        self.assertFalse(gate(control_ultralytics, control_fixed, low_recall)["passed"])
        low_f1 = dict(passing, f1=0.627)
        self.assertFalse(gate(control_ultralytics, control_fixed, low_f1)["passed"])


if __name__ == "__main__":
    unittest.main()
